                                                )
                        EXEC DBShrpn.dbo.usp_hsp_upd_hasg_reassign
                              @asg_cur_id                  = @emp_id                                    -- char(15)
                            , @asg_cur_assign_to           = @v_ASSIGNED_TO_CODE                        -- char(01)
