                            AND (assigned_to_code   = @v_ASSIGNED_TO_CODE)
                            AND (job_or_pos_id      = @job_or_pos_id)
                            AND (eff_date           = @eff_date)
                            AND (next_eff_date      = @v_END_OF_TIME_DATE)


