    DECLARE @tax_ceiling_amt                            money        -- employee.user_monetary_amt_1
    DECLARE @labor_grp_code                             char(5)         -- DBShrpn..emp_employment.labor_grp_code
    DECLARE @file_source                                char(50)        -- 'SS VENUS' or 'SS GANYMEDE'
