       datetime       not null,   user_ind_1                     char(1)       not null,   user_ind_2                     char(1)       not null,   user_text_1                    char(50)       not null,   user_text_2                    char(50)       not null,   t4_employ_code                 char(2)       not null,   chgstamp                       smallint       not null)
