        -- Pay Element (Event 06)
        ---------------------------------------------------------------------------
        SET @v_step_position = 'Execute DBShrpn.dbo.usp_ins_pay_element'
        SET @v_event_id = @v_EVENT_ID_PAY_ELE
        SET @w_status = 0   -- reset return code

        IF  EXISTS (
