     /* @W_ACTION_DATETIME  char(30) *//* R6.5.03M-ALS#28859: moved to above */

--exec @ret = sp_dbs_authenticate
--if @ret != 0 return

declare	@w_end_of_time				datetime,
	@w_status_code				char(1),
